dirs=['nw','ne','se','sw']; entries=[]; metrics={}; frames={}
def bands(values):
 ids=np.where(values>10)[0]; groups=[]
 for v in ids:
  if not groups or v>groups[-1][-1]+5:groups.append([int(v)])
  else:groups[-1].append(int(v))
 return [(g[0],g[-1]+1) for g in groups if len(g)>20]
def extract(p):
 im=Image.open(p).convert('RGBA'); ar=np.array(im); cells=[]
 rows=bands((ar[:,:,3]>24).sum(axis=1));assert len(rows)==4,(p,rows)
 for top,bottom in rows:
  cols=bands((ar[top:bottom,:,3]>24).sum(axis=0));assert len(cols)==4,(p,cols)
  for left,right in cols:
   cell=im.crop((max(0,left-12),max(0,top-12),min(im.width,right+12),min(im.height,bottom+12)))
   data=np.array(cell);data[:,:,3][data[:,:,3]<20]=0
   cell=Image.fromarray(data);bb=cell.getchannel('A').getbbox()
   assert bb and bb[0]>0 and bb[1]>0 and bb[2]<cell.width and bb[3]<cell.height,(p,bb)
   cells.append((cell,bb))
 return cells
for kind,p in D['sources'].items():
 cells=extract(p)
 scales={}
 if kind=='scenario':
  for r,d in enumerate(dirs):scales[r]=112/statistics.median(b[3]-b[1] for _,b in cells[r*4:r*4+4])
 else:
  scale=112/statistics.median(b[3]-b[1] for _,b in cells[:4]);scales={r:scale for r in range(4)}
 metrics[kind]={'scales':scales,'sourceSha256':hashlib.sha256(Path(p).read_bytes()).hexdigest()}
 for i,(cell,bb) in enumerate(cells):
  r,c=divmod(i,4);d=dirs[r] if kind=='scenario' else kind;action=0 if kind=='scenario' else r
  family='scenario-v1' if kind=='scenario' else 'combat-v1';sc=scales[r]
  crop=cell.crop(bb);w,h=round(crop.width*sc),round(crop.height*sc)
  crop=crop.resize((w,h),Image.Resampling.LANCZOS)
  # Ground anchor is the midpoint of visible boots, not fan or upper robe.
  a=np.array(cell.getchannel('A')); ys,xs=np.where((a>80)&(np.indices(a.shape)[0]>=bb[3]-max(6,round((bb[3]-bb[1])*.065))))
  anchor=(int(xs.min())+int(xs.max())+1)/2
  x=round(80-(anchor-bb[0])*sc);y=150-h
  assert x>=4 and x+w<=156 and y>=4,(kind,i,x,y,w,h)
  target=Image.new('RGBA',(160,160));target.alpha_composite(crop,(x,y))
  path=OUT/family/f'{d}-{action}-{c}.webp';path.parent.mkdir(parents=True,exist_ok=True)
  target.save(path,'WEBP',quality=78,method=6)
  check=Image.open(path).convert('RGBA');b=check.getchannel('A').getbbox();assert check.size==(160,160) and b[3]==150
  entries.append({'path':str(path.relative_to(ROOT)),'direction':d,'action':action,'frame':c,'bytes':path.stat().st_size,'bbox':b,'sha256':hashlib.sha256(path.read_bytes()).hexdigest()})
  frames[(family,d,action,c)]=check
